/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field seasonCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableSeasonCode extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, seasonCode);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    RetailInventTable retailInventTable;
    while select seasonCode from retailInventTable
        group by seasonCode
    {
        ret.add(retailInventTable.seasonCode);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, seasonCode));
    qbr.value(queryValue(_value));
}
